cd /Users/jacob.zweifel/workspace/malpercio-dev/ezpds/.claude/worktrees/serene-lichterman-c2f0f0
# Find the review thread whose first comment DB id == 3525118223, then resolve it
THREAD_ID=$(gh api graphql -f query='
query($owner:String!,$repo:String!,$pr:Int!){
  repository(owner:$owner,name:$repo){
    pullRequest(number:$pr){
      reviewThreads(first:50){
        nodes{ id isResolved comments(first:1){ nodes{ databaseId } } }
      }
    }
  }
}' -F owner=malpercio-dev -F repo=ezpds -F pr=109 \
  --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.comments.nodes[0].databaseId==3525118223) | .id')
echo "thread: $THREAD_ID"
if [ -n "$THREAD_ID" ]; then
  gh api graphql -f query='
  mutation($id:ID!){ resolveReviewThread(input:{threadId:$id}){ thread{ isResolved } } }' \
    -F id="$THREAD_ID" --jq '.data.resolveReviewThread.thread.isResolved' 2>&1 | sed 's/^/resolved: /'
else
  echo "thread not found (comment may be a top-level review comment, not a thread)"
fi

